(() => {
  if (window.StillProfessionalV136) return;
  const money = (value, currency = 'EUR') => Number.isFinite(value) ? new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(value / 100) : '—';
  const upperWords = value => String(value || '').replaceAll('_', ' ').toLocaleLowerCase().replace(/(^|\s)\S/g, letter => letter.toLocaleUpperCase());
  const capabilityCategories = ['DESIGN','DEVELOPMENT','WRITING','TRANSLATION','MARKETING','PHOTO_VIDEO','AUDIO','CONSULTING','EDUCATION','HOME_SERVICE','REPAIR','INSTALLATION','CREATIVE','ADMIN','OTHER'];
  const status = (value, h) => `<span class="spn136-status" data-state="${h.esc(value || '')}">${h.esc(upperWords(value))}</span>`;

  function accountSection(h) {
    return `<section class="spn136-account" data-professional-account><div><small>${h.t('WORK WITH STILL', 'RADI UZ STILL')}</small><h3>${h.t('Professional Mode', 'Profesionalni način')}</h3><p>${h.t('Use the same Still identity to help with real Needs. Your private World is never part of your professional profile.', 'Istim Still identitetom pomaži sa stvarnim potrebama. Tvoj privatni Svijet nikada nije dio profesionalnog profila.')}</p></div><button type="button" data-open-professional-settings>${h.t('Set up Professional Mode', 'Postavi Profesionalni način')} <span>→</span></button><a href="/app/work" data-nav hidden>${h.t('Open Work', 'Otvori Posao')} →</a></section>`;
  }

  async function professionalDialog(h) {
    const [data, portfolioData] = await Promise.all([h.api('/api/v1/professional/profile'), h.api('/api/v1/professional/portfolio')]), profile = data.profile || {}, capabilities = data.capabilities || [], portfolio = portfolioData.portfolio || [];
    const dialog = h.openDialog(h.t('Professional Mode', 'Profesionalni način'), `<section class="spn136-settings"><header><span>${h.t('SAME IDENTITY · SEPARATE CONTEXT', 'ISTI IDENTITET · ODVOJEN KONTEKST')}</span><h2>${h.t('Work with Still.', 'Radi uz Still.')}</h2><p>${h.t('Only this professional profile and work you explicitly accept can be seen by clients.', 'Klijenti mogu vidjeti samo ovaj profesionalni profil i posao koji izričito prihvatiš.')}</p></header><form data-professional-profile>
      <label class="spn136-toggle"><input type="checkbox" name="professionalModeEnabled" ${profile.professionalModeEnabled ? 'checked' : ''}><span><b>${h.t('Enable Professional Mode', 'Uključi Profesionalni način')}</b><small>${h.t('You can pause or disable it at any time.', 'Možeš ga pauzirati ili isključiti u bilo kojem trenutku.')}</small></span></label>
      <label>${h.t('Professional name', 'Profesionalno ime')}<input name="displayName" required minlength="2" maxlength="120" value="${h.esc(profile.displayName || '')}"></label>
      <label>${h.t('What do you help with?', 'U čemu pomažeš?')}<input name="headline" maxlength="180" value="${h.esc(profile.headline || '')}" placeholder="${h.t('e.g. Brand designer for independent businesses', 'npr. Dizajner brenda za male tvrtke')}"></label>
      <label>${h.t('Short professional introduction', 'Kratko profesionalno predstavljanje')}<textarea name="bio" maxlength="1500">${h.esc(profile.bio || '')}</textarea></label>
      <div class="spn136-form-grid"><label>${h.t('Availability', 'Dostupnost')}<select name="availabilityStatus">${['AVAILABLE','LIMITED','UNAVAILABLE','PAUSED'].map(value => `<option value="${value}" ${profile.availabilityStatus === value ? 'selected' : ''}>${h.t(upperWords(value), upperWords(value))}</option>`).join('')}</select></label><label>${h.t('Coarse location', 'Okvirna lokacija')}<input name="coarseLocation" maxlength="120" value="${h.esc(profile.coarseLocation || '')}" placeholder="Zagreb"></label></div>
      <fieldset><legend>${h.t('How you work', 'Kako radiš')}</legend>${['REMOTE','LOCAL','HYBRID'].map(value => `<label><input type="checkbox" name="locationModes" value="${value}" ${(profile.locationModes || []).includes(value) ? 'checked' : ''}>${h.t(upperWords(value), upperWords(value))}</label>`).join('')}</fieldset>
      <div class="spn136-form-grid"><label>${h.t('Weekly capacity (optional)', 'Tjedni kapacitet (neobavezno)')}<input type="number" name="weeklyCapacityHours" min="1" max="168" value="${profile.weeklyCapacityHours || ''}"></label><label>${h.t('Minimum project (optional, EUR)', 'Najmanji projekt (neobavezno, EUR)')}<input type="number" name="minimumProject" min="0" step="0.01" value="${Number.isFinite(profile.minimumProjectCents) ? profile.minimumProjectCents / 100 : ''}"></label></div>
      <button class="primary">${h.t('Save Professional Mode', 'Spremi Profesionalni način')}</button><p role="status" data-profile-status></p></form>
      <section class="spn136-capabilities"><header><h3>${h.t('Capability Passport', 'Putovnica sposobnosti')}</h3><p>${h.t('Declared capabilities remain unverified until real evidence supports them.', 'Prijavljene sposobnosti ostaju nepotvrđene dok ih ne podupre stvarni dokaz.')}</p></header><div>${capabilities.map(capability => `<article><div><b>${h.esc(capability.name)}</b><small>${h.esc(upperWords(capability.category))} · ${h.esc(upperWords(capability.verificationStatus))}</small></div><span>${capability.evidenceCount}</span></article>`).join('') || `<p>${h.t('No capabilities added yet.', 'Još nema dodanih sposobnosti.')}</p>`}</div><form data-capability-form><label>${h.t('Capability', 'Sposobnost')}<input name="name" required minlength="2" maxlength="120"></label><label>${h.t('Category', 'Kategorija')}<select name="category">${capabilityCategories.map(value => `<option>${value}</option>`).join('')}</select></label><button>${h.t('Add capability', 'Dodaj sposobnost')}</button></form></section>
      <section class="spn136-portfolio"><header><h3>${h.t('Work evidence', 'Dokazi rada')}</h3><p>${h.t('Add only real work you are allowed to share. Linked capabilities gain evidence, not automatic verification.', 'Dodaj samo stvaran rad koji smiješ dijeliti. Povezane sposobnosti dobivaju dokaz, ne automatsku potvrdu.')}</p></header><div>${portfolio.map(item => `<article><div><b>${h.esc(item.title)}</b><small>${h.esc(item.description || '')}</small></div>${item.external_url ? `<a href="${h.esc(item.external_url)}" target="_blank" rel="noopener noreferrer">${h.t('Open', 'Otvori')}</a>` : ''}</article>`).join('') || `<p>${h.t('No work evidence added yet.', 'Još nema dodanih dokaza rada.')}</p>`}</div><form data-portfolio-form><label>${h.t('Work sample title', 'Naziv primjera rada')}<input name="title" required minlength="2" maxlength="180"></label><label>${h.t('Description', 'Opis')}<textarea name="description" maxlength="2000"></textarea></label><label>${h.t('HTTPS link (optional)', 'HTTPS poveznica (neobavezno)')}<input name="externalUrl" type="url" placeholder="https://"></label>${capabilities.length ? `<fieldset><legend>${h.t('Capabilities this supports', 'Sposobnosti koje ovo podupire')}</legend>${capabilities.map(capability => `<label><input type="checkbox" name="capabilityKeys" value="${h.esc(capability.key)}">${h.esc(capability.name)}</label>`).join('')}</fieldset>` : ''}<button>${h.t('Add work evidence', 'Dodaj dokaz rada')}</button></form></section></section>`, 'spn136-dialog');
    const profileForm = dialog.querySelector('[data-professional-profile]');
    profileForm.addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget, values = Object.fromEntries(new FormData(form)), button = form.querySelector('button'), output = form.querySelector('[data-profile-status]'); button.disabled = true; try { const modes = [...form.querySelectorAll('[name="locationModes"]:checked')].map(input => input.value); await h.api('/api/v1/professional/profile', { method: profile.publicId ? 'PATCH' : 'POST', body: JSON.stringify({ ...values, professionalModeEnabled: form.elements.professionalModeEnabled.checked, locationModes: modes, minimumProjectCents: values.minimumProject ? Math.round(Number(values.minimumProject) * 100) : null, weeklyCapacityHours: values.weeklyCapacityHours ? Number(values.weeklyCapacityHours) : null, currency: 'EUR' }) }); output.textContent = h.t('Professional Mode saved.', 'Profesionalni način je spremljen.'); h.invalidate(); } catch (error) { output.textContent = error.message; button.disabled = false; } });
    dialog.querySelector('[data-capability-form]').addEventListener('submit', async event => { event.preventDefault(); const button = event.currentTarget.querySelector('button'); button.disabled = true; try { await h.api('/api/v1/professional/capabilities', { method: 'POST', body: JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); dialog.close(); professionalDialog(h); } catch (error) { h.setStatus(error.message, true); button.disabled = false; } });
    dialog.querySelector('[data-portfolio-form]').addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget, values = Object.fromEntries(new FormData(form)), button = form.querySelector('button'); button.disabled = true; try { await h.api('/api/v1/professional/portfolio', { method: 'POST', body: JSON.stringify({ ...values, capabilityKeys: [...form.querySelectorAll('[name="capabilityKeys"]:checked')].map(input => input.value), isPublic: true }) }); dialog.close(); professionalDialog(h); } catch (error) { h.setStatus(error.message, true); button.disabled = false; } });
  }

  async function bindAccount(h) {
    const section = document.querySelector('[data-professional-account]'); if (!section || section.dataset.bound) return; section.dataset.bound = '1';
    section.querySelector('[data-open-professional-settings]').addEventListener('click', () => professionalDialog(h));
    try { const data = await h.api('/api/v1/professional/profile'); if (data.profile?.professionalModeEnabled) { section.querySelector('h3').textContent = data.profile.headline || h.t('Professional Mode is ready', 'Profesionalni način je spreman'); section.querySelector('button').textContent = h.t('Edit professional profile', 'Uredi profesionalni profil'); section.querySelector('a').hidden = false; } } catch {}
  }

  function nowSection(data, h) {
    if (!data || (!data.enabled && !(data.notifications || []).length && !(data.activeProjects || []).length)) return '';
    const items = [...(data.notifications || []).map(item => ({ title: item.title, detail: item.body, href: item.href })), ...(data.activeProjects || []).map(item => ({ title: item.title, detail: upperWords(item.status), href: `/app/work/project/${item.public_id}` }))].slice(0, 5);
    return `<section class="spn136-now"><header><div><span>${h.t('WORK', 'POSAO')}</span><h2>${h.t('Professional work that needs you', 'Profesionalni posao koji te treba')}</h2></div><a href="/app/work" data-nav>${h.t('Open Work', 'Otvori Posao')} →</a></header>${items.length ? `<div>${items.map(item => `<a href="${h.esc(item.href)}" data-nav><div><b>${h.esc(item.title)}</b><small>${h.esc(item.detail || '')}</small></div><span>→</span></a>`).join('')}</div>` : `<p>${h.t('No professional work needs attention.', 'Nijedan profesionalni posao ne traži pažnju.')}</p>`}</section>`;
  }

  function hireSection(data, h) {
    if (data?.need?.type !== 'HIRE' || ['RESOLVED','DISMISSED','CANCELLED'].includes(data.need.status)) return '';
    return `<section class="sos133-workspace-section spn136-hire"><header><span>${h.t('GET HELP', 'PRONAĐI POMOĆ')}</span><h2>${h.t('Find the right person for this Need.', 'Pronađi pravu osobu za ovu potrebu.')}</h2><p>${h.t('Review a private Still Brief first. Nothing is shared until you choose who receives it.', 'Prvo pregledaj privatni Still sažetak. Ništa se ne dijeli dok ne odabereš tko ga prima.')}</p></header><button type="button" class="primary" data-open-hire-flow>${h.t('Prepare Still Brief', 'Pripremi Still sažetak')} <span>→</span></button></section>`;
  }

  async function hireDialog(data, h) {
    const need = data.need, [existing, documents] = await Promise.all([h.api(`/api/v1/world/needs/${encodeURIComponent(need.publicId)}/brief`), h.api('/api/v1/world/documents').catch(() => ({ documents: [] }))]), brief = existing.brief || {};
    const dialog = h.openDialog(h.t('Get professional help', 'Pronađi profesionalnu pomoć'), `<section class="spn136-brief-flow"><header><span>${h.t('YOUR STILL BRIEF', 'TVOJ STILL SAŽETAK')}</span><h2>${h.esc(need.title)}</h2><p>${h.t('Still can organize what you provide. You review and confirm every shared detail.', 'Still može organizirati ono što navedeš. Ti pregledavaš i potvrđuješ svaki podijeljeni detalj.')}</p></header><form data-brief-form>
      <label>${h.t('What should be achieved?', 'Što treba postići?')}<textarea name="objective" required minlength="2" maxlength="1200">${h.esc(brief.objective || need.desiredOutcome || need.description || need.title)}</textarea></label>
      <label>${h.t('What is included?', 'Što je uključeno?')}<textarea name="scope" required minlength="2" maxlength="3000">${h.esc(brief.scope || need.description || need.title)}</textarea></label>
      <label>${h.t('Expected deliverables (one per line)', 'Očekivane isporuke (jedna po retku)')}<textarea name="deliverables" maxlength="1800">${h.esc((brief.deliverables || []).join('\n'))}</textarea></label>
      <label>${h.t('Constraints (one per line)', 'Ograničenja (jedno po retku)')}<textarea name="constraints" maxlength="2400">${h.esc((brief.constraints || []).join('\n'))}</textarea></label>
      <div class="spn136-form-grid"><label>${h.t('Maximum budget (EUR, optional)', 'Najveći proračun (EUR, neobavezno)')}<input type="number" name="budgetMax" min="0" step="0.01" value="${Number.isFinite(brief.budgetMaxCents) ? brief.budgetMaxCents / 100 : ''}"></label><label>${h.t('Deadline (optional)', 'Rok (neobavezno)')}<input type="date" name="deadline" value="${h.esc(brief.deadline || need.deadline || '')}"></label></div>
      <div class="spn136-form-grid"><label>${h.t('Work location', 'Mjesto rada')}<select name="locationMode"><option value="">${h.t('Not specified', 'Nije određeno')}</option>${['REMOTE','LOCAL','HYBRID'].map(value => `<option value="${value}" ${brief.locationMode === value ? 'selected' : ''}>${upperWords(value)}</option>`).join('')}</select></label><label>${h.t('Coarse location', 'Okvirna lokacija')}<input name="coarseLocation" maxlength="120" value="${h.esc(brief.coarseLocation || '')}" placeholder="Zagreb"></label></div>
      ${(documents.documents || []).length ? `<fieldset><legend>${h.t('Documents you explicitly approve', 'Dokumenti koje izričito odobravaš')}</legend>${documents.documents.slice(0, 20).map(document => `<label><input type="checkbox" name="attachments" value="${h.esc(document.publicId)}" ${(brief.attachments || []).some(item => item.public_id === document.publicId || item.publicId === document.publicId) ? 'checked' : ''}>${h.esc(document.title)}</label>`).join('')}</fieldset>` : ''}
      <label class="spn136-toggle"><input type="checkbox" name="confirm" required ${brief.confirmedAt ? 'checked' : ''}><span><b>${h.t('I reviewed this brief', 'Pregledao/la sam ovaj sažetak')}</b><small>${h.t('Enable matching only after this confirmation.', 'Povezivanje se uključuje tek nakon ove potvrde.')}</small></span></label>
      <button class="primary">${h.t('Confirm and find help', 'Potvrdi i pronađi pomoć')}</button></form><div data-matches></div></section>`, 'spn136-dialog');
    const form = dialog.querySelector('[data-brief-form]');
    form.addEventListener('submit', async event => { event.preventDefault(); const button = form.querySelector('.primary'), values = Object.fromEntries(new FormData(form)); button.disabled = true; try { await h.api(`/api/v1/world/needs/${encodeURIComponent(need.publicId)}/brief`, { method: 'POST', body: JSON.stringify({ title: need.title, objective: values.objective, scope: values.scope, deliverables: values.deliverables.split('\n').map(value => value.trim()).filter(Boolean), constraints: values.constraints.split('\n').map(value => value.trim()).filter(Boolean), budgetMaxCents: values.budgetMax ? Math.round(Number(values.budgetMax) * 100) : null, deadline: values.deadline || null, locationMode: values.locationMode || null, coarseLocation: values.coarseLocation || null, attachmentIds: [...form.querySelectorAll('[name="attachments"]:checked')].map(input => input.value), confirm: form.elements.confirm.checked, matchingEnabled: true }) }); const result = await h.api(`/api/v1/world/needs/${encodeURIComponent(need.publicId)}/professional-matches`); renderMatches(dialog.querySelector('[data-matches]'), result, need, h, dialog); } catch (error) { h.setStatus(error.message, true); button.disabled = false; } });
    if (brief.confirmedAt && brief.matchingEnabled) { try { renderMatches(dialog.querySelector('[data-matches]'), await h.api(`/api/v1/world/needs/${encodeURIComponent(need.publicId)}/professional-matches`), need, h, dialog); } catch {} }
  }

  function renderMatches(host, result, need, h, dialog) {
    const matches = result.matches || []; host.innerHTML = matches.length ? `<section class="spn136-matches"><header><span>${h.t('REAL MATCHES', 'STVARNA PODUDARANJA')}</span><h3>${h.t(matches.length === 1 ? 'One person can help.' : `${matches.length} people can help.`, matches.length === 1 ? 'Jedna osoba može pomoći.' : `${matches.length} osobe mogu pomoći.`)}</h3><p>${h.t('Choose who receives your confirmed brief.', 'Odaberi tko prima tvoj potvrđeni sažetak.')}</p></header><form data-share-brief>${matches.map((match, index) => `<label><input type="checkbox" name="professionals" value="${h.esc(match.professional.publicId)}" ${index === 0 ? 'checked' : ''}><span><b>${h.esc(match.professional.displayName)}</b><small>${h.esc(match.professional.headline || '')}</small>${match.matchReasons.map(reason => `<em>✓ ${h.esc(reason)}</em>`).join('')}</span></label>`).join('')}<button class="primary">${h.t('Send selected brief', 'Pošalji odabrani sažetak')}</button></form></section>` : `<section class="spn136-empty"><h3>${h.esc(result.emptyState?.title || h.t('No matching professionals are available yet.', 'Još nema dostupnih odgovarajućih profesionalaca.'))}</h3><p>${h.t('Adjust the brief, continue externally, invite someone, or keep this Need saved. Still will not invent a provider.', 'Prilagodi sažetak, nastavi izvan Stilla, pozovi nekoga ili spremi potrebu. Still neće izmisliti pružatelja.')}</p></section>`;
    const share = host.querySelector('[data-share-brief]'); if (!share) return; share.addEventListener('submit', async event => { event.preventDefault(); const selected = [...share.querySelectorAll('[name="professionals"]:checked')].map(input => input.value); if (!selected.length) return h.setStatus(h.t('Choose at least one person.', 'Odaberi barem jednu osobu.'), true); share.querySelector('button').disabled = true; try { await h.api(`/api/v1/world/needs/${encodeURIComponent(need.publicId)}/brief/share`, { method: 'POST', body: JSON.stringify({ professionalIds: selected }) }); dialog.close(); h.setStatus(h.t('Brief sent only to the people you selected.', 'Sažetak je poslan samo osobama koje si odabrao/la.')); h.invalidate(); h.renderNeed(need.publicId); } catch (error) { h.setStatus(error.message, true); share.querySelector('button').disabled = false; } });
  }

  function bindHire(data, h) { document.querySelector('[data-open-hire-flow]')?.addEventListener('click', () => hireDialog(data, h)); }

  async function renderWorkHome(host, h) {
    const data = await h.api('/api/v1/professional/work'), enabled = data.profile?.professionalModeEnabled;
    host.innerHTML = `<section class="spn136-work"><button type="button" class="sos133-back" data-back>← ${h.t('Back', 'Natrag')}</button><header class="spn136-work-head"><div><span>${h.t('WORK', 'POSAO')}</span><h1>${h.t('Resolve real Needs.', 'Riješi stvarne potrebe.')}</h1><p>${h.t('Opportunities, agreed work and review—kept in the same calm Still context.', 'Prilike, dogovoreni posao i pregled—u istom mirnom Still kontekstu.')}</p></div><button type="button" data-open-professional-settings>${enabled ? h.t('Professional profile', 'Profesionalni profil') : h.t('Enable Professional Mode', 'Uključi Profesionalni način')}</button></header>
      ${enabled ? `<section class="spn136-availability"><div><small>${h.t('AVAILABILITY', 'DOSTUPNOST')}</small><b>${h.esc(upperWords(data.profile.availabilityStatus))}</b></div><p>${h.esc(data.profile.headline || h.t('Add a headline so clients understand how you help.', 'Dodaj naslov kako bi klijenti razumjeli kako pomažeš.'))}</p><button type="button" data-open-professional-settings>${h.t('Change', 'Promijeni')}</button></section>` : `<section class="spn136-empty"><h2>${h.t('Professional Mode is off.', 'Profesionalni način je isključen.')}</h2><p>${h.t('Enable it only if you want real matching opportunities. Your private World remains private.', 'Uključi ga samo ako želiš stvarne prilike. Tvoj privatni Svijet ostaje privatan.')}</p><button class="primary" data-open-professional-settings>${h.t('Set up Professional Mode', 'Postavi Profesionalni način')}</button></section>`}
      ${(data.notifications || []).filter(item => !item.read_at).length ? `<section class="spn136-work-section"><header><span>${h.t('NEEDS YOU', 'TREBA TEBE')}</span><h2>${h.t('Current attention', 'Trenutačna pažnja')}</h2></header><div class="spn136-work-list">${data.notifications.filter(item => !item.read_at).slice(0, 8).map(item => `<a href="${h.esc(item.href)}" data-nav><div><b>${h.esc(item.title)}</b><small>${h.esc(item.body || '')}</small></div><span>→</span></a>`).join('')}</div></section>` : ''}
      <section class="spn136-work-section"><header><span>${h.t('ACTIVE WORK', 'AKTIVNI POSAO')}</span><h2>${h.t('Projects in motion', 'Projekti u tijeku')}</h2></header>${(data.projects || []).filter(item => !['COMPLETED','CANCELLED'].includes(item.status)).length ? `<div class="spn136-work-list">${data.projects.filter(item => !['COMPLETED','CANCELLED'].includes(item.status)).map(item => `<a href="/app/work/project/${h.esc(item.public_id)}" data-nav><div><b>${h.esc(item.title)}</b><small>${h.esc(item.viewer_role === 'CLIENT' ? h.t('You hired help', 'Angažirao/la si pomoć') : h.t('You are helping', 'Ti pomažeš'))} · ${h.esc(upperWords(item.status))}${item.due_at ? ` · ${h.date(item.due_at)}` : ''}</small></div><span>→</span></a>`).join('')}</div>` : `<p class="spn136-muted">${h.t('No active projects.', 'Nema aktivnih projekata.')}</p>`}</section>
      ${enabled ? `<section class="spn136-work-section"><header><span>${h.t('OPPORTUNITIES', 'PRILIKE')}</span><h2>${h.t('Briefs shared with you', 'Sažeci podijeljeni s tobom')}</h2></header>${(data.opportunities || []).length ? `<div class="spn136-work-list">${data.opportunities.map(item => `<a href="/app/work/opportunity/${h.esc(item.public_id)}" data-nav><div><b>${h.esc(item.title)}</b><small>${status(item.status, h)}${item.deadline ? ` · ${h.date(item.deadline)}` : ''}</small></div><span>→</span></a>`).join('')}</div>` : `<p class="spn136-muted">${h.t('No matching brief has been shared with you.', 'Nijedan odgovarajući sažetak nije podijeljen s tobom.')}</p>`}</section>` : ''}
      ${(data.projects || []).some(item => item.status === 'COMPLETED') ? `<section class="spn136-work-section"><header><span>${h.t('COMPLETED', 'DOVRŠENO')}</span><h2>${h.t('Work history', 'Povijest rada')}</h2></header><div class="spn136-work-list">${data.projects.filter(item => item.status === 'COMPLETED').map(item => `<a href="/app/work/project/${h.esc(item.public_id)}" data-nav><div><b>${h.esc(item.title)}</b><small>${item.completed_at ? h.date(item.completed_at) : ''}</small></div><span>→</span></a>`).join('')}</div></section>` : ''}</section>`;
    h.bindContent(); host.querySelectorAll('[data-open-professional-settings]').forEach(button => button.addEventListener('click', () => professionalDialog(h)));
  }

  function proposalForm(opportunity, h) {
    return `<form class="spn136-proposal-form" data-proposal-form><header><span>${h.t('YOUR PROPOSAL', 'TVOJA PONUDA')}</span><h2>${h.t('Offer clear terms.', 'Ponudi jasne uvjete.')}</h2></header><div class="spn136-form-grid"><label>${h.t('Amount (EUR)', 'Iznos (EUR)')}<input name="amount" type="number" min="0.01" step="0.01" required></label><label>${h.t('Estimated days', 'Procijenjeni broj dana')}<input name="estimatedDays" type="number" min="1" max="3650"></label></div><label>${h.t('What you will do', 'Što ćeš napraviti')}<textarea name="scope" required minlength="2" maxlength="4000"></textarea></label><label>${h.t('Short message', 'Kratka poruka')}<textarea name="summary" required minlength="2" maxlength="2000"></textarea></label><div class="spn136-form-grid"><label>${h.t('First milestone', 'Prva etapa')}<input name="milestone" maxlength="180" placeholder="${h.t('Final delivery', 'Završna isporuka')}"></label><label>${h.t('Deadline (optional)', 'Rok (neobavezno)')}<input name="deadline" type="date"></label></div><button class="primary">${h.t('Send proposal', 'Pošalji ponudu')}</button><small>${h.t('Payment is external. Still does not hold funds or provide escrow.', 'Plaćanje je vanjsko. Still ne drži sredstva niti pruža escrow.')}</small></form>`;
  }

  function counterDialog(proposal, h, rerender) {
    const dialog = h.openDialog(h.t('Update proposal terms', 'Ažuriraj uvjete ponude'), `<form class="spn136-submit" data-counter-proposal><p>${h.t('Every change creates a new permanent proposal version for both sides.', 'Svaka promjena stvara novu trajnu verziju ponude za obje strane.')}</p><div class="spn136-form-grid"><label>${h.t('Amount (EUR)', 'Iznos (EUR)')}<input name="amount" type="number" min="0.01" step="0.01" required value="${Number(proposal.amount_cents || 0) / 100}"></label><label>${h.t('Estimated days', 'Procijenjeni broj dana')}<input name="estimatedDays" type="number" min="1" max="3650" value="${proposal.estimated_days || ''}"></label></div><label>${h.t('Scope', 'Opseg')}<textarea name="scope" required minlength="2" maxlength="4000">${h.esc(proposal.scope || '')}</textarea></label><label>${h.t('Summary', 'Sažetak')}<textarea name="summary" required minlength="2" maxlength="2000">${h.esc(proposal.summary || '')}</textarea></label><div class="spn136-form-grid"><label>${h.t('Deadline', 'Rok')}<input name="deadline" type="date" value="${h.esc(proposal.deadline || '')}"></label><label>${h.t('Revision rounds', 'Krugovi dorade')}<input name="revisionRounds" type="number" min="0" max="50" value="${proposal.revision_rounds || 0}"></label></div><label>${h.t('What changed?', 'Što je promijenjeno?')}<textarea name="changeNote" required minlength="2" maxlength="600"></textarea></label><button class="primary">${h.t('Send updated terms', 'Pošalji ažurirane uvjete')}</button></form>`, 'spn136-dialog');
    dialog.querySelector('form').addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget, values = Object.fromEntries(new FormData(form)); form.querySelector('button').disabled = true; try { await h.api(`/api/v1/professional/proposals/${encodeURIComponent(proposal.public_id)}`, { method: 'PATCH', body: JSON.stringify({ ...values, amountCents: Math.round(Number(values.amount) * 100), estimatedDays: values.estimatedDays ? Number(values.estimatedDays) : null, revisionRounds: Number(values.revisionRounds || 0), currency: proposal.currency || 'EUR', milestones: proposal.milestones || [] }) }); dialog.close(); rerender(); } catch (error) { h.setStatus(error.message, true); form.querySelector('button').disabled = false; } });
  }

  function safetyDialog({ projectId = null, professionalId = null, mode = 'report' }, h, rerender) {
    const blocking = mode === 'block', dialog = h.openDialog(h.t(blocking ? 'Block professional' : 'Report a concern', blocking ? 'Blokiraj profesionalca' : 'Prijavi problem'), `<form class="spn136-submit"><p>${h.t(blocking ? 'Blocking removes this professional from future matches and prevents further professional contact.' : 'Describe a real safety, conduct, or trust concern. A report does not promise arbitration or a particular outcome.', blocking ? 'Blokiranje uklanja ovog profesionalca iz budućih povezivanja i sprječava daljnji profesionalni kontakt.' : 'Opiši stvaran problem sigurnosti, ponašanja ili povjerenja. Prijava ne obećava arbitražu ni određeni ishod.')}</p>${blocking ? '' : `<label>${h.t('Reason', 'Razlog')}<input name="reason" required minlength="3" maxlength="120"></label><label>${h.t('Details', 'Detalji')}<textarea name="details" maxlength="2000"></textarea></label>`}<button class="primary">${h.t(blocking ? 'Confirm block' : 'Send report', blocking ? 'Potvrdi blokiranje' : 'Pošalji prijavu')}</button></form>`, 'spn136-dialog');
    dialog.querySelector('form').addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget; form.querySelector('button').disabled = true; try { const values = Object.fromEntries(new FormData(form)); await h.api(blocking ? '/api/v1/professional/blocks' : '/api/v1/professional/reports', { method: 'POST', body: JSON.stringify(blocking ? { professionalId } : { ...values, projectId, professionalId }) }); dialog.close(); h.setStatus(h.t(blocking ? 'Professional blocked.' : 'Report recorded.', blocking ? 'Profesionalac je blokiran.' : 'Prijava je zabilježena.')); rerender?.(); } catch (error) { h.setStatus(error.message, true); form.querySelector('button').disabled = false; } });
  }

  async function renderOpportunity(host, id, h) {
    const response = await h.api(`/api/v1/professional/opportunities/${encodeURIComponent(id)}`), opportunity = response.opportunity; if (opportunity.proposal) { const detail = await h.api(`/api/v1/professional/proposals/${encodeURIComponent(opportunity.proposal.public_id)}`); opportunity.proposal.versions = detail.proposal.versions || []; } const professional = opportunity.viewerRole === 'PROFESSIONAL', proposal = opportunity.proposal;
    host.innerHTML = `<section class="spn136-opportunity"><button type="button" class="sos133-back" data-back>← ${h.t('Back', 'Natrag')}</button><header><span>${h.t('STILL BRIEF', 'STILL SAŽETAK')}</span><h1>${h.esc(opportunity.brief.title)}</h1><p>${h.esc(opportunity.brief.objective)}</p><div>${status(opportunity.status, h)}<small>${professional ? h.esc(opportunity.client.displayName) : h.esc(opportunity.professional.displayName)}</small></div></header><div class="spn136-opportunity-grid"><main><section><h2>${h.t('Scope', 'Opseg')}</h2><p>${h.esc(opportunity.brief.scope)}</p></section>${opportunity.brief.deliverables.length ? `<section><h2>${h.t('Deliverables', 'Isporuke')}</h2><ul>${opportunity.brief.deliverables.map(item => `<li>${h.esc(item)}</li>`).join('')}</ul></section>` : ''}${opportunity.brief.constraints.length ? `<section><h2>${h.t('Constraints', 'Ograničenja')}</h2><ul>${opportunity.brief.constraints.map(item => `<li>${h.esc(item)}</li>`).join('')}</ul></section>` : ''}${opportunity.brief.attachments.length ? `<section><h2>${h.t('Shared files', 'Podijeljene datoteke')}</h2>${opportunity.brief.attachments.map(document => `<a class="spn136-file" href="/api/v1/professional/opportunities/${encodeURIComponent(id)}/documents/${encodeURIComponent(document.public_id)}/file"><b>${h.esc(document.title)}</b><span>${h.esc(document.mime_type)}</span></a>`).join('')}</section>` : ''}<section><h2>${h.t('Questions', 'Pitanja')}</h2><div class="spn136-messages">${opportunity.messages.map(message => `<p class="${message.author === 'YOU' ? 'you' : ''}">${h.esc(message.body)}</p>`).join('')}</div><form data-opportunity-question><textarea name="question" required maxlength="2000" placeholder="${h.t('Ask only what the brief does not answer…', 'Pitaj samo ono što sažetak ne odgovara…')}"></textarea><button>${h.t('Ask', 'Pitaj')}</button></form></section></main><aside><section class="spn136-terms"><span>${h.t('TERMS', 'UVJETI')}</span><dl><div><dt>${h.t('Budget', 'Proračun')}</dt><dd>${opportunity.brief.budgetMaxCents ? h.esc(money(opportunity.brief.budgetMaxCents, opportunity.brief.currency)) : h.t('Not set', 'Nije određen')}</dd></div><div><dt>${h.t('Deadline', 'Rok')}</dt><dd>${opportunity.brief.deadline ? h.date(opportunity.brief.deadline) : h.t('Not set', 'Nije određen')}</dd></div><div><dt>${h.t('Location', 'Lokacija')}</dt><dd>${h.esc([opportunity.brief.locationMode, opportunity.brief.coarseLocation].filter(Boolean).join(' · ') || h.t('Not set', 'Nije određena'))}</dd></div></dl>${professional && !proposal ? `<div class="spn136-interest"><button class="primary" data-opportunity-action="INTERESTED">${h.t('I am interested', 'Zainteresiran/a sam')}</button><button data-opportunity-action="DECLINED">${h.t('Decline', 'Odbij')}</button></div>` : ''}</section>${proposal ? `<section class="spn136-proposal"><span>${h.t('PROPOSAL', 'PONUDA')}</span><h2>${h.esc(money(proposal.amount_cents, proposal.currency))}</h2><p>${h.esc(proposal.summary)}</p><dl><div><dt>${h.t('Timeline', 'Trajanje')}</dt><dd>${proposal.estimated_days ? `${proposal.estimated_days} ${h.t('days', 'dana')}` : '—'}</dd></div><div><dt>${h.t('Status', 'Status')}</dt><dd>${h.esc(upperWords(proposal.status))}</dd></div></dl>${!professional && ['SENT','VIEWED','COUNTERED'].includes(proposal.status) ? `<button class="primary" data-proposal-accept="${h.esc(proposal.public_id)}">${h.t('Accept proposal', 'Prihvati ponudu')}</button><button data-proposal-decline="${h.esc(proposal.public_id)}">${h.t('Decline', 'Odbij')}</button>` : ''}${professional && ['SENT','VIEWED','COUNTERED'].includes(proposal.status) ? `<button data-proposal-withdraw="${h.esc(proposal.public_id)}">${h.t('Withdraw', 'Povuci')}</button>` : ''}</section>` : professional ? proposalForm(opportunity, h) : `<section class="spn136-empty compact"><p>${h.t('No proposal has arrived yet.', 'Ponuda još nije stigla.')}</p></section>`}</aside></div></section>`;
    h.bindContent();
    if (proposal && ['SENT','VIEWED','COUNTERED'].includes(proposal.status)) { const panel = host.querySelector('.spn136-proposal'), counter = document.createElement('button'); counter.type = 'button'; counter.dataset.proposalCounter = proposal.public_id; counter.textContent = h.t('Suggest different terms', 'Predloži drukčije uvjete'); panel?.append(counter); if ((proposal.versions || []).length > 1) { const history = document.createElement('details'), summary = document.createElement('summary'), list = document.createElement('ol'); summary.textContent = h.t(`Terms history (${proposal.versions.length})`, `Povijest uvjeta (${proposal.versions.length})`); for (const version of proposal.versions) { const item = document.createElement('li'); item.textContent = `${h.t('Version', 'Verzija')} ${version.version_number} · ${money(version.amount_cents, version.currency)} · ${upperWords(version.author_role)}${version.change_note ? ` · ${version.change_note}` : ''}`; list.append(item); } history.append(summary, list); panel?.append(history); } }
    if (!professional) { const panel = host.querySelector('.spn136-terms'), safety = document.createElement('div'); safety.className = 'spn136-safety'; safety.innerHTML = `<button type="button" data-safety-report>${h.t('Report concern', 'Prijavi problem')}</button><button type="button" class="danger" data-safety-block>${h.t('Block this professional', 'Blokiraj ovog profesionalca')}</button>`; panel?.append(safety); }
    host.querySelectorAll('[data-opportunity-action]').forEach(button => button.addEventListener('click', async () => { button.disabled = true; await h.api(`/api/v1/professional/opportunities/${encodeURIComponent(id)}/interest`, { method: 'POST', body: JSON.stringify({ action: button.dataset.opportunityAction }) }); renderOpportunity(host, id, h); }));
    host.querySelector('[data-opportunity-question]')?.addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget; await h.api(`/api/v1/professional/opportunities/${encodeURIComponent(id)}/interest`, { method: 'POST', body: JSON.stringify({ action: 'QUESTION', question: form.elements.question.value }) }); renderOpportunity(host, id, h); });
    host.querySelector('[data-proposal-form]')?.addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget, values = Object.fromEntries(new FormData(form)); form.querySelector('button').disabled = true; try { await h.api('/api/v1/professional/proposals', { method: 'POST', body: JSON.stringify({ opportunityId: id, amountCents: Math.round(Number(values.amount) * 100), currency: 'EUR', estimatedDays: values.estimatedDays ? Number(values.estimatedDays) : null, scope: values.scope, summary: values.summary, deadline: values.deadline || null, milestones: [{ title: values.milestone || h.t('Final delivery', 'Završna isporuka'), dueAt: values.deadline || null }] }) }); renderOpportunity(host, id, h); } catch (error) { h.setStatus(error.message, true); form.querySelector('button').disabled = false; } });
    host.querySelector('[data-proposal-counter]')?.addEventListener('click', () => counterDialog(proposal, h, () => renderOpportunity(host, id, h)));
    host.querySelector('[data-safety-report]')?.addEventListener('click', () => safetyDialog({ professionalId: opportunity.professional.publicId }, h));
    host.querySelector('[data-safety-block]')?.addEventListener('click', () => safetyDialog({ professionalId: opportunity.professional.publicId, mode: 'block' }, h, () => h.navigate('/app/work')));
    host.querySelector('[data-proposal-accept]')?.addEventListener('click', async event => { event.currentTarget.disabled = true; try { const result = await h.api(`/api/v1/professional/proposals/${encodeURIComponent(event.currentTarget.dataset.proposalAccept)}`, { method: 'PATCH', body: JSON.stringify({ action: 'ACCEPT' }) }); h.navigate(`/app/work/project/${encodeURIComponent(result.projectId)}`); } catch (error) { h.setStatus(error.message, true); event.currentTarget.disabled = false; } });
    for (const [selector, action] of [['[data-proposal-decline]','DECLINE'],['[data-proposal-withdraw]','WITHDRAW']]) host.querySelector(selector)?.addEventListener('click', async event => { const proposalId = event.currentTarget.dataset.proposalDecline || event.currentTarget.dataset.proposalWithdraw; await h.api(`/api/v1/professional/proposals/${encodeURIComponent(proposalId)}`, { method: 'PATCH', body: JSON.stringify({ action }) }); renderOpportunity(host, id, h); });
  }

  async function documentChoices(h) { const data = await h.api('/api/v1/world/documents').catch(() => ({ documents: [] })); return (data.documents || []).map(document => `<option value="${h.esc(document.publicId)}">${h.esc(document.title)}</option>`).join(''); }
  async function submitDialog(project, milestone, h, rerender) {
    const choices = await documentChoices(h), dialog = h.openDialog(h.t('Submit milestone', 'Predaj etapu'), `<form class="spn136-submit" data-submit-milestone><p>${h.esc(milestone.title)}</p><label>${h.t('Deliverable title', 'Naziv isporuke')}<input name="title" required minlength="2" maxlength="180" value="${h.esc(milestone.title)}"></label><label>${h.t('What changed or is ready?', 'Što je promijenjeno ili spremno?')}<textarea name="description" maxlength="2000"></textarea></label>${choices ? `<label>${h.t('Private Still document (optional)', 'Privatni Still dokument (neobavezno)')}<select name="documentId"><option value="">${h.t('No file', 'Bez datoteke')}</option>${choices}</select></label>` : ''}<label>${h.t('External HTTPS link (optional)', 'Vanjska HTTPS poveznica (neobavezno)')}<input name="externalUrl" type="url" placeholder="https://"></label><button class="primary">${h.t('Submit for review', 'Predaj na pregled')}</button><small>${h.t('Previous submissions remain in project history.', 'Prethodne predaje ostaju u povijesti projekta.')}</small></form>`, 'spn136-dialog');
    dialog.querySelector('form').addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget, values = Object.fromEntries(new FormData(form)); form.querySelector('button').disabled = true; try { await h.api(`/api/v1/professional/milestones/${encodeURIComponent(milestone.publicId)}/submit`, { method: 'POST', body: JSON.stringify(values) }); dialog.close(); rerender(); } catch (error) { h.setStatus(error.message, true); form.querySelector('button').disabled = false; } });
  }
  function revisionDialog(milestone, h, rerender) { const dialog = h.openDialog(h.t('Request revision', 'Zatraži doradu'), `<form class="spn136-submit"><p>${h.esc(milestone.title)}</p><label>${h.t('What needs to change?', 'Što treba promijeniti?')}<textarea name="reason" required minlength="3" maxlength="1200"></textarea></label><button class="primary">${h.t('Request revision', 'Zatraži doradu')}</button></form>`, 'spn136-dialog'); dialog.querySelector('form').addEventListener('submit', async event => { event.preventDefault(); await h.api(`/api/v1/professional/milestones/${encodeURIComponent(milestone.publicId)}/revision`, { method: 'POST', body: JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); dialog.close(); rerender(); }); }
  function feedbackDialog(project, h, rerender) { const dialog = h.openDialog(h.t('Project feedback', 'Povratna informacija o projektu'), `<form class="spn136-submit"><p>${h.t('Feedback is available only for this completed project.', 'Povratna informacija dostupna je samo za ovaj dovršeni projekt.')}</p>${[['outcomeRating','Outcome','Ishod'],['communicationRating','Communication','Komunikacija'],['reliabilityRating','Reliability','Pouzdanost']].map(([name,en,hr]) => `<label>${h.t(en,hr)}<select name="${name}" required><option value="">—</option>${[5,4,3,2,1].map(value => `<option value="${value}">${value}</option>`).join('')}</select></label>`).join('')}<label>${h.t('Comment (optional)', 'Komentar (neobavezno)')}<textarea name="comment" maxlength="1200"></textarea></label><button class="primary">${h.t('Save feedback', 'Spremi povratnu informaciju')}</button></form>`, 'spn136-dialog'); dialog.querySelector('form').addEventListener('submit', async event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)); await h.api(`/api/v1/professional/projects/${encodeURIComponent(project.publicId)}/feedback`, { method: 'POST', body: JSON.stringify({ ...values, outcomeRating: Number(values.outcomeRating), communicationRating: Number(values.communicationRating), reliabilityRating: Number(values.reliabilityRating) }) }); dialog.close(); rerender(); }); }
  function milestoneDialog(project, h, rerender) { const dialog = h.openDialog(h.t('Add agreed milestone', 'Dodaj dogovorenu etapu'), `<form class="spn136-submit"><p>${h.t('Milestones can be added only by the client before work submissions begin.', 'Etape može dodati samo klijent prije početka predaje rada.')}</p><label>${h.t('Milestone', 'Etapa')}<input name="title" required minlength="2" maxlength="180"></label><label>${h.t('Description', 'Opis')}<textarea name="description" maxlength="1200"></textarea></label><div class="spn136-form-grid"><label>${h.t('Amount (EUR, optional)', 'Iznos (EUR, neobavezno)')}<input name="amount" type="number" min="0" step="0.01"></label><label>${h.t('Due date', 'Rok')}<input name="dueAt" type="date"></label></div><button class="primary">${h.t('Add milestone', 'Dodaj etapu')}</button></form>`, 'spn136-dialog'); dialog.querySelector('form').addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget, values = Object.fromEntries(new FormData(form)); await h.api(`/api/v1/professional/projects/${encodeURIComponent(project.publicId)}/milestones`, { method: 'POST', body: JSON.stringify({ ...values, amountCents: values.amount ? Math.round(Number(values.amount) * 100) : null, currency: project.deal.currency }) }); dialog.close(); rerender(); }); }
  function projectActionDialog(project, action, h, rerender) { const dispute = action === 'dispute', dialog = h.openDialog(h.t(dispute ? 'Open project dispute' : 'Cancel project', dispute ? 'Otvori spor projekta' : 'Otkaži projekt'), `<form class="spn136-submit"><p>${h.t(dispute ? 'Still records the dispute and preserves the project history. Still does not currently provide human arbitration.' : 'Cancellation is available only before any milestone is completed. The project history remains preserved.', dispute ? 'Still bilježi spor i čuva povijest projekta. Still trenutačno ne pruža ljudsku arbitražu.' : 'Otkazivanje je dostupno samo prije dovršetka bilo koje etape. Povijest projekta ostaje sačuvana.')}</p><label>${h.t('Reason', 'Razlog')}<input name="reason" required minlength="3" maxlength="120"></label>${dispute ? `<label>${h.t('Details', 'Detalji')}<textarea name="details" required minlength="3" maxlength="3000"></textarea></label>` : ''}<button class="primary">${h.t(dispute ? 'Record dispute' : 'Confirm cancellation', dispute ? 'Zabilježi spor' : 'Potvrdi otkazivanje')}</button></form>`, 'spn136-dialog'); dialog.querySelector('form').addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget; form.querySelector('button').disabled = true; try { await h.api(`/api/v1/professional/projects/${encodeURIComponent(project.publicId)}/${action}`, { method: 'POST', body: JSON.stringify(Object.fromEntries(new FormData(form))) }); dialog.close(); rerender(); } catch (error) { h.setStatus(error.message, true); form.querySelector('button').disabled = false; } }); }

  async function renderProject(host, id, h) {
    const { project } = await h.api(`/api/v1/professional/projects/${encodeURIComponent(id)}`), client = project.viewerRole === 'CLIENT', rerender = () => renderProject(host, id, h);
    host.innerHTML = `<section class="spn136-project"><button type="button" class="sos133-back" data-back>← ${h.t('Back', 'Natrag')}</button><header><span>${h.t('PROJECT', 'PROJEKT')}</span><h1>${h.esc(project.title)}</h1><p>${h.esc(project.nextAction)}</p><div>${status(project.status, h)}<small>${client ? h.t('You hired', 'Angažirao/la si') : h.t('You are helping', 'Ti pomažeš')}: ${h.esc(client ? project.participants.professional.displayName : project.participants.client.displayName)}</small></div></header><div class="spn136-project-grid"><main><section class="spn136-brief-summary"><span>${h.t('AGREED BRIEF', 'DOGOVORENI SAŽETAK')}</span><h2>${h.esc(project.brief.objective)}</h2><p>${h.esc(project.brief.scope)}</p></section><section class="spn136-milestones"><header><span>${h.t('MILESTONES', 'ETAPE')}</span><h2>${h.t('Progress with explicit review.', 'Napredak uz izričit pregled.')}</h2></header><ol>${project.milestones.map((milestone, index) => `<li data-state="${h.esc(milestone.status)}"><span>${milestone.status === 'COMPLETED' ? '✓' : index + 1}</span><div><small>${h.esc(upperWords(milestone.status))}${milestone.dueAt ? ` · ${h.date(milestone.dueAt)}` : ''}</small><h3>${h.esc(milestone.title)}</h3><p>${h.esc(milestone.description || '')}</p><div>${!client && ['PENDING','IN_PROGRESS','REVISION_REQUESTED'].includes(milestone.status) ? `<button class="primary" data-submit-milestone="${h.esc(milestone.publicId)}">${h.t(milestone.status === 'REVISION_REQUESTED' ? 'Submit revision' : 'Submit milestone', milestone.status === 'REVISION_REQUESTED' ? 'Predaj doradu' : 'Predaj etapu')}</button>` : ''}${client && milestone.status === 'SUBMITTED' ? `<button class="primary" data-approve-milestone="${h.esc(milestone.publicId)}">${h.t('Approve', 'Odobri')}</button><button data-revise-milestone="${h.esc(milestone.publicId)}">${h.t('Request revision', 'Zatraži doradu')}</button>` : ''}</div></div></li>`).join('')}</ol></section>${project.deliverables.length ? `<section class="spn136-deliverables"><header><span>${h.t('DELIVERABLES', 'ISPORUKE')}</span><h2>${h.t('Every submission remains visible.', 'Svaka predaja ostaje vidljiva.')}</h2></header>${project.deliverables.map(deliverable => `<article><div><small>${h.esc(upperWords(deliverable.status))} · ${h.date(deliverable.submitted_at)}</small><b>${h.esc(deliverable.title)}</b><p>${h.esc(deliverable.description || '')}</p></div>${deliverable.document_public_id ? `<a href="/api/v1/professional/deliverables/${encodeURIComponent(deliverable.public_id)}/file">${h.t('Download private file', 'Preuzmi privatnu datoteku')}</a>` : deliverable.external_url ? `<a href="${h.esc(deliverable.external_url)}" target="_blank" rel="noopener noreferrer">${h.t('Open link', 'Otvori poveznicu')}</a>` : ''}</article>`).join('')}</section>` : ''}<section class="spn136-history"><header><span>${h.t('HISTORY', 'POVIJEST')}</span><h2>${h.t('Project record', 'Zapis projekta')}</h2></header>${h.historyList(project.history.map(event => ({ title: event.title, occurredAt: event.created_at })))}</section></main><aside><section class="spn136-deal"><span>${h.t('AGREED TERMS', 'DOGOVORENI UVJETI')}</span><h2>${h.esc(money(project.deal.amountCents, project.deal.currency))}</h2><p>${h.esc(project.deal.paymentNotice || '')}</p><dl><div><dt>${h.t('Payment', 'Plaćanje')}</dt><dd>${h.esc(upperWords(project.deal.paymentStatus))}</dd></div><div><dt>${h.t('Still fee', 'Still naknada')}</dt><dd>${h.esc(money(project.deal.stillFeeCents, project.deal.currency))}</dd></div><div><dt>${h.t('Target', 'Cilj')}</dt><dd>${project.dueAt ? h.date(project.dueAt) : '—'}</dd></div></dl>${client && project.allMilestonesComplete && project.status !== 'COMPLETED' ? `<button class="primary" data-complete-project>${h.t('Confirm final outcome', 'Potvrdi završni ishod')}</button>` : ''}${client && project.status === 'COMPLETED' && !project.feedback ? `<button data-project-feedback>${h.t('Leave project feedback', 'Ostavi povratnu informaciju')}</button><button data-project-favorite>${h.t('Would work with again', 'Ponovno bih surađivao/la')}</button>` : ''}</section><section class="spn136-project-chat"><h2>${h.t('Project messages', 'Poruke projekta')}</h2><div>${project.messages.map(message => `<p class="${message.author === 'YOU' ? 'you' : ''}">${h.esc(message.body)}</p>`).join('')}</div>${!['COMPLETED','CANCELLED'].includes(project.status) ? `<form data-project-message><textarea name="message" required maxlength="2000"></textarea><button>${h.t('Send', 'Pošalji')}</button></form>` : ''}</section></aside></div></section>`;
    h.bindContent();
    if (client && ['NOT_STARTED','ACTIVE'].includes(project.status) && project.milestones.every(item => ['PENDING','CANCELLED'].includes(item.status))) { const header = host.querySelector('.spn136-milestones header'), add = document.createElement('button'); add.type = 'button'; add.dataset.addMilestone = '1'; add.textContent = h.t('Add agreed milestone', 'Dodaj dogovorenu etapu'); header?.append(add); }
    if (!['COMPLETED','CANCELLED'].includes(project.status)) { const deal = host.querySelector('.spn136-deal'), safety = document.createElement('div'); safety.className = 'spn136-safety'; safety.innerHTML = `<button type="button" data-project-report>${h.t('Report concern', 'Prijavi problem')}</button><button type="button" data-project-dispute>${h.t('Open dispute', 'Otvori spor')}</button>${client ? `<button type="button" data-project-block>${h.t('Block professional', 'Blokiraj profesionalca')}</button>` : ''}<button type="button" class="danger" data-project-cancel>${h.t('Cancel project', 'Otkaži projekt')}</button>`; deal?.append(safety); }
    host.querySelector('[data-add-milestone]')?.addEventListener('click', () => milestoneDialog(project, h, rerender));
    host.querySelector('[data-project-report]')?.addEventListener('click', () => safetyDialog({ projectId: project.publicId }, h));
    host.querySelector('[data-project-block]')?.addEventListener('click', () => safetyDialog({ professionalId: project.participants.professional.publicId, mode: 'block' }, h, () => h.navigate('/app/work')));
    host.querySelector('[data-project-dispute]')?.addEventListener('click', () => projectActionDialog(project, 'dispute', h, rerender));
    host.querySelector('[data-project-cancel]')?.addEventListener('click', () => projectActionDialog(project, 'cancel', h, rerender));
    host.querySelectorAll('[data-submit-milestone]').forEach(button => button.addEventListener('click', () => submitDialog(project, project.milestones.find(item => item.publicId === button.dataset.submitMilestone), h, rerender)));
    host.querySelectorAll('[data-approve-milestone]').forEach(button => button.addEventListener('click', async () => { button.disabled = true; await h.api(`/api/v1/professional/milestones/${encodeURIComponent(button.dataset.approveMilestone)}/approve`, { method: 'POST', body: '{}' }); rerender(); }));
    host.querySelectorAll('[data-revise-milestone]').forEach(button => button.addEventListener('click', () => revisionDialog(project.milestones.find(item => item.publicId === button.dataset.reviseMilestone), h, rerender)));
    host.querySelector('[data-complete-project]')?.addEventListener('click', async event => { event.currentTarget.disabled = true; await h.api(`/api/v1/professional/projects/${encodeURIComponent(id)}/complete`, { method: 'POST', body: JSON.stringify({ summary: project.title }) }); h.invalidate(); rerender(); });
    host.querySelector('[data-project-feedback]')?.addEventListener('click', () => feedbackDialog(project, h, rerender));
    host.querySelector('[data-project-favorite]')?.addEventListener('click', async event => { event.currentTarget.disabled = true; await h.api(`/api/v1/professional/projects/${encodeURIComponent(id)}/favorite`, { method: 'POST', body: '{}' }); event.currentTarget.textContent = h.t('Saved as trusted professional', 'Spremljeno kao pouzdani profesionalac'); });
    host.querySelector('[data-project-message]')?.addEventListener('submit', async event => { event.preventDefault(); await h.api(`/api/v1/professional/projects/${encodeURIComponent(id)}/messages`, { method: 'POST', body: JSON.stringify({ message: event.currentTarget.elements.message.value }) }); rerender(); });
  }

  async function render({ host, route, helpers: h }) { host.innerHTML = h.loading(h.t('Opening Work…', 'Otvaram Posao…')); try { if (route.kind === 'opportunity' && route.id) return await renderOpportunity(host, route.id, h); if (route.kind === 'project' && route.id) return await renderProject(host, route.id, h); return await renderWorkHome(host, h); } catch (error) { host.innerHTML = h.failed(error.message); h.bindContent(); } }

  window.StillProfessionalV136 = { accountSection, bindAccount, nowSection, hireSection, bindHire, render, openSettings: professionalDialog };
})();
